func testAccResourceAutoF5XCAlertPolicyConfig(name, receiverName, namespace, description, matcherType, actionType, groupByType, matcherOverride string) string {
	matcher := matcherOverride
	if matcher == "" {
		if matcherType == "any" {
			matcher = `matcher_choice = {
      any = true
    }`
		}
	}

	action := "send = true"
	if actionType == "dont_send" {
		action = "dont_send = true"
	}

	groupBy := "individual = true"
	if groupByType == "ves_io_group" {
		groupBy = "ves_io_group = true"
	}

	return fmt.Sprintf(`
%s
resource "f5xc_alert_policy" "example" {
  name        = %q
  namespace   = %q
  description = %q

  receivers = [
    {
      name      = f5xc_alert_receiver.example.name
      namespace = f5xc_alert_receiver.example.namespace
    }
  ]

  routes = [
    {
      %s
      action_choice = {
        %s
      }
    }
  ]

  notification_parameters = {
    group_by_choice = {
      %s
    }
    group_wait      = "30s"
    group_interval  = "1m"
    repeat_interval = "4h"
  }
}
`, testAccResourceAutoF5XCAlertPolicyReceiverConfig(receiverName, namespace), name, namespace, description, matcher, action, groupBy)
}

